// Storage for uploaded medicine images.
//
// Locally (`node server.js`) images live in backend/uploads and are served by
// express.static. On Netlify the API runs as a serverless function whose disk
// is read-only and short-lived, so multer writes to the temp directory and the
// file is then moved into the "medicine-images" Netlify Blobs store.
//
// Demo images generated by `npm run seed:data` are committed to the repository
// (backend/uploads/seed-*.svg) and bundled with the function, so they are served
// from the bundle when no Blob exists for that name.
const express = require('express');
const fs = require('fs');
const os = require('os');
const path = require('path');

const SERVERLESS = process.env.MEDITRACK_SERVERLESS === '1';
const STORE_NAME = 'medicine-images';

// Read/write location for multer uploads.
const UPLOADS_DIR = SERVERLESS
  ? path.join(os.tmpdir(), 'meditrack-uploads')
  : path.join(__dirname, '..', 'uploads');
// Images committed to git (the seed catalogue) are read-only at runtime.
const BUNDLED_UPLOADS_DIR = path.join(__dirname, '..', 'uploads');

if (!fs.existsSync(UPLOADS_DIR)) {
  fs.mkdirSync(UPLOADS_DIR, { recursive: true });
}

const MIME_TYPES = {
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
};

function mimeFor(filename) {
  return MIME_TYPES[path.extname(filename).toLowerCase()] || 'application/octet-stream';
}

function blobStore() {
  // Loaded lazily so local development and tests never need @netlify/blobs.
  const { getStore } = require('@netlify/blobs');
  return getStore({ name: STORE_NAME, consistency: 'strong' });
}

/** Middleware: after multer, move the uploaded file into Blobs (serverless only). */
async function persistUpload(req, res, next) {
  if (!SERVERLESS || !req.file) return next();
  try {
    const data = await fs.promises.readFile(req.file.path);
    await blobStore().set(req.file.filename, data, {
      metadata: { contentType: req.file.mimetype },
    });
    fs.unlink(req.file.path, () => {});
    return next();
  } catch (err) {
    return next(err);
  }
}

/** Delete a stored image, ignoring "already gone" errors. */
function removeUpload(filename) {
  if (!filename) return;
  if (SERVERLESS) {
    blobStore()
      .delete(filename)
      .catch(() => {});
    return;
  }
  fs.unlink(path.join(UPLOADS_DIR, filename), () => {});
}

/** Router that serves stored images under /uploads. */
function serveUploads() {
  if (!SERVERLESS) return express.static(UPLOADS_DIR);

  const router = express.Router();
  router.get('/:name', async (req, res, next) => {
    // basename() prevents `..%2F` traversal in a function URL.
    const name = path.basename(String(req.params.name || ''));
    if (!name) return res.status(404).end();

    try {
      const entry = await blobStore().getWithMetadata(name, { type: 'arrayBuffer' });
      if (entry) {
        res.set('Content-Type', entry.metadata?.contentType || mimeFor(name));
        res.set('Cache-Control', 'public, max-age=31536000, immutable');
        return res.send(Buffer.from(entry.data));
      }

      // A demo image shipped with the repository (see `npm run seed:data`).
      const bundled = path.join(BUNDLED_UPLOADS_DIR, name);
      if (fs.existsSync(bundled)) {
        res.set('Content-Type', mimeFor(name));
        res.set('Cache-Control', 'public, max-age=3600');
        return res.sendFile(bundled);
      }

      return res.status(404).end();
    } catch (err) {
      return next(err);
    }
  });
  return router;
}

module.exports = { UPLOADS_DIR, persistUpload, removeUpload, serveUploads };
